from src.shared.domain.entities.user import User from src.shared.domain.enums.state_enum import STATE from src.shared.helpers.errors.usecase_errors import NoItemsFound from src.shared.infra.repositories.user_repository_mock import UserRepositoryMock import pytest
class Test_UserRepositoryMock: def test_get_user(self): repo = UserRepositoryMock() user = repo.get_user(1)
assert user.name == "Bruno Soller" assert user.email == "soller@soller.com" assert user.user_id == 1 assert user.state == STATE.APPROVED
def test_get_user_not_found(self): repo = UserRepositoryMock() with pytest.raises(NoItemsFound): user = repo.get_user(69)
def test_get_all_user(self): repo = UserRepositoryMock() users = repo.get_all_user() assert len(users) == 3
def test_create_user(self): repo = UserRepositoryMock() user = User( name="Vitor Soller", email="dohype@vitin.com", user_id=4, state=STATE.PENDING )
repo.create_user(user)
assert repo.users[3].name == "Vitor Soller" assert repo.users[3].email == "dohype@vitin.com" assert repo.users[3].user_id == 4 assert repo.users[3].state == STATE.PENDING
assert repo.user_counter == 4
def test_delete_user(self): repo = UserRepositoryMock() user = repo.delete_user(1) assert user.name == "Bruno Soller" assert user.email == "soller@soller.com" assert user.user_id == 1 assert user.state == STATE.APPROVED
def test_delete_user_not_found(self): repo = UserRepositoryMock() with pytest.raises(NoItemsFound): user = repo.delete_user(69)
def test_update_user(self): repo = UserRepositoryMock() user = repo.update_user(1, "Bruno Guirão")
assert user.name == "Bruno Guirão" assert repo.users[0].name == "Bruno Guirão"
def test_update_user_not_found(self): repo = UserRepositoryMock() with pytest.raises(NoItemsFound): user = repo.update_user(69, "Bruno Guirão")
def test_get_users_counter(self): repo = UserRepositoryMock()
assert repo.get_user_counter() == 3

from src.shared.domain.entities.user import User
from src.shared.domain.enums.state_enum import STATE
from src.shared.helpers.errors.domain_errors import EntityError
import pytest


class Test_User:
    def test_user(self):
        User(name="VITOR", email="21.01444-2@maua.br", user_id=1, state=STATE.APPROVED)

    def test_user_name_is_none(self):
        with pytest.raises(EntityError):
            User(name=None, email="21.01444-2@maua.br", user_id=1, state=STATE.APPROVED)

    def test_user_name_is_not_str(self):
        with pytest.raises(EntityError):
            User(name=1, email="21.01444-2@maua.br", user_id=1, state=STATE.APPROVED)

    def test_user_name_is_shorter_than_min_length(self):
        with pytest.raises(EntityError):
            User(name="V", email="21.01444-2@maua.br", user_id=1, state=STATE.APPROVED)

    def test_user_email_is_none(self):
        with pytest.raises(EntityError):
            User(name="VITOR", email=None, user_id=1, state=STATE.APPROVED)

    def test_user_email_is_not_valid(self):
        with pytest.raises(EntityError):
            User(name="VITOR", email="21.01444-2maua.br", user_id=1, state=STATE.APPROVED)

    def test_user_user_id_is_not_int(self):
        with pytest.raises(EntityError):
            User(name="VITOR", email="21.01444-2@maua.br", user_id="1", state=STATE.APPROVED)

    def test_user_user_id_is_negative(self):
        with pytest.raises(EntityError):
            User(name="VITOR", email="21.01444-2@maua.br", user_id=-1, state=STATE.APPROVED)

    def test_user_state_is_not_sate_enum(self):
        with pytest.raises(EntityError):
            User(name="VITOR", email="21.01444-2@maua.br", user_id=1, state="APPROVED")

