from aws_cdk import ( # Duration, Stack, # aws_sqs as sqs, ) from constructs import Construct from aws_cdk.aws_apigateway import RestApi, Cors
from .lambda_stack import LambdaStack from .template_dynamo_table import TemplateDynamoTable
class TemplateStack(Stack):
def __init__(self, scope: Construct, construct_id: str, **kwargs) -> None: super().__init__(scope, construct_id, **kwargs)
self.rest_api = RestApi(self, "Template_RestApi", rest_api_name="Template_RestApi", description="This is the Template RestApi", default_cors_preflight_options= { "allow_origins": Cors.ALL_ORIGINS, "allow_methods": ["GET", "POST", "PUT", "DELETE", "OPTIONS"], "allow_headers": ["*"] }, )
api_gateway_resource = self.rest_api.root.add_resource("mss-template", default_cors_preflight_options= { "allow_origins": Cors.ALL_ORIGINS, "allow_methods": ["GET", "POST", "PUT", "DELETE", "OPTIONS"], "allow_headers": Cors.DEFAULT_HEADERS } )
self.dynamo_table = TemplateDynamoTable(self, "TemplateDynamoTable")
ENVIRONMENT_VARIABLES = { "STAGE": "DEV", "DYNAMO_TABLE_NAME": self.dynamo_table.table.table_name, "DYNAMO_PARTITION_KEY": "PK", "DYNAMO_SORT_KEY": "SK", "REGION": self.region, }
self.lambda_stack = LambdaStack(self, api_gateway_resource=api_gateway_resource, environment_variables=ENVIRONMENT_VARIABLES)
for function in self.lambda_stack.functions_that_need_dynamo_permissions: self.dynamo_table.table.grant_read_write_data(function)

from decimal import Decimal
from aws_cdk import (
    aws_dynamodb as dynamodb, RemovalPolicy,
)
from constructs import Construct


class TemplateDynamoTable(Construct):
    table: dynamodb.Table

    def __init__(self, scope: Construct, construct_id: str, **kwargs) -> None:
        super().__init__(scope, construct_id, **kwargs)

        self.table = dynamodb.Table(
            self, "TemplateDynamoTable",
            partition_key=dynamodb.Attribute(
                name="PK",
                type=dynamodb.AttributeType.STRING
            ),
            sort_key=dynamodb.Attribute(
                name="SK",
                type=dynamodb.AttributeType.STRING
            ), 
            billing_mode=dynamodb.BillingMode.PAY_PER_REQUEST,
            removal_policy=RemovalPolicy.DESTROY
        )

